import{_ as e,o as r,c as d,ag as o,j as s}from"./chunks/framework.KxDd3USm.js";const u=JSON.parse('{"title":"06.5 TCP、UDP 与三次握手 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"06-计算机网络/05-TCP与UDP.md","filePath":"06-计算机网络/05-TCP与UDP.md"}'),n={name:"06-计算机网络/05-TCP与UDP.md"},a={class:"fig"},g={"data-figure-id":"figure-20",viewBox:"0 0 720 330",width:"100%",style:{"max-width":"720px"},role:"img","aria-label":"TCP 三次握手时序图。客户端 A 从 CLOSED 发送 SYN seq x 进入 SYN-SENT；服务器 B 在 LISTEN 收到后发送 SYN 加 ACK，seq y ack x 加一，进入 SYN-RCVD；客户端 A 回 ACK，seq x 加一 ack y 加一，进入 ESTABLISHED，服务器 B 收到后也进入 ESTABLISHED。"};function c(l,t,h,p,i,S){return r(),d("div",null,[t[2]||(t[2]=o('<h1 id="_06-5-tcp、udp-与三次握手-★★★" tabindex="-1">06.5 TCP、UDP 与三次握手 ★★★ <a class="header-anchor" href="#_06-5-tcp、udp-与三次握手-★★★" aria-label="Permalink to &quot;06.5 TCP、UDP 与三次握手 ★★★&quot;">​</a></h1><h3 id="为什么要分-tcp-和-udp-两种" tabindex="-1">为什么要分 TCP 和 UDP 两种 <a class="header-anchor" href="#为什么要分-tcp-和-udp-两种" aria-label="Permalink to &quot;为什么要分 TCP 和 UDP 两种&quot;">​</a></h3><p>传输层负责&quot;程序到程序&quot;的交付（用<strong>端口号</strong>区分同一台主机上的不同应用）。有的应用宁可慢也要<strong>一条都不能丢</strong>（网页、文件、邮件），有的应用宁可丢也要<strong>快</strong>（直播、语音、域名查询）。于是传输层提供两种选择：</p><table tabindex="0"><thead><tr><th>对比项</th><th><strong>TCP</strong></th><th><strong>UDP</strong></th></tr></thead><tbody><tr><td>连接</td><td><strong>面向连接</strong>（先握手再传数据）</td><td><strong>无连接</strong>（拿到地址直接发）</td></tr><tr><td>可靠性</td><td><strong>可靠</strong>（确认、重传、按序交付）</td><td><strong>不可靠</strong>（尽力而为，丢了不补）</td></tr><tr><td>有序性</td><td>保证按序到达</td><td>不保证顺序</td></tr><tr><td>流量控制/拥塞控制</td><td><strong>有</strong>（滑动窗口）</td><td>没有</td></tr><tr><td>开销与速度</td><td>头部大、开销大、较慢</td><td>头部小（8 字节）、开销小、<strong>快</strong></td></tr><tr><td>数据单位</td><td>字节流</td><td>用户数据报</td></tr><tr><td>典型应用</td><td>HTTP/HTTPS、FTP、SMTP、TELNET</td><td><strong>DNS、DHCP、TFTP</strong>、SNMP、音视频流</td></tr></tbody></table><p><strong>共同点</strong>（考过原型的知识点）：TCP 和 UDP <strong>都用端口号标识上层应用</strong>（端口寻址）；都基于 IP 之上、属于传输层。但 UDP <strong>没有</strong>连接管理、没有重传、没有流量控制。</p><p><strong>反例演示</strong>：</p><ol><li>&quot;UDP 是不可靠协议，所以 UDP 报文没有端口&quot;——<strong>错</strong>。可靠不可靠是传输质量，端口寻址是编址方式，UDP 同样用端口（如 DNS 用 53）。</li><li>&quot;TCP 因为可靠，所以比 UDP 一定更快&quot;——<strong>反了</strong>。确认重传换可靠，代价就是速度；要快用 UDP。</li><li>&quot;DNS 是传输层协议&quot;——<strong>错</strong>。DNS 是<strong>应用层</strong>协议，只是它<strong>使用 UDP</strong>（端口 53）来传输，别把&quot;用谁传输&quot;和&quot;属于哪层&quot;混为一谈。</li></ol><h3 id="tcp-三次握手-背报文-背状态" tabindex="-1">TCP 三次握手（背报文 + 背状态） <a class="header-anchor" href="#tcp-三次握手-背报文-背状态" aria-label="Permalink to &quot;TCP 三次握手（背报文 + 背状态）&quot;">​</a></h3><p><strong>动机</strong>：TCP 要在传数据前确认&quot;双方都具备收发能力&quot;。为什么<strong>三次</strong>而不是两次？——两次握手下，服务器无法确认&quot;客户端能收到我发的数据&quot;；且历史上一个早已失效的连接请求若突然到达服务器，两次握手会让服务器白白建起一条没人用的连接。第三次握手让客户端把&quot;我收到了你的确认&quot;再告诉服务器，双方的收发能力才都被双向确认。</p><p>三次握手过程（客户端 A，服务器 B）：</p><table tabindex="0"><thead><tr><th>步骤</th><th>谁发什么</th><th>报文标志</th><th>本步的状态变化（谁变了、变成什么）</th></tr></thead><tbody><tr><td>1</td><td>A → B：请求建立连接</td><td><strong>SYN=1</strong>（seq=x）</td><td><strong>A</strong>：CLOSED → <strong>SYN-SENT</strong>；B 仍停在 LISTEN</td></tr><tr><td>2</td><td>B → A：同意并确认</td><td><strong>SYN=1, ACK=1</strong>（seq=y, ack=x+1）</td><td><strong>B</strong>：LISTEN → <strong>SYN-RCVD</strong>；A 仍停在 SYN-SENT</td></tr><tr><td>3</td><td>A → B：确认</td><td><strong>ACK=1</strong>（seq=x+1, ack=y+1）</td><td><strong>A</strong>：SYN-SENT → <strong>ESTABLISHED</strong>；<strong>B</strong>：SYN-RCVD → <strong>ESTABLISHED</strong></td></tr></tbody></table><blockquote><p>这张表的&quot;谁&quot;会随着步骤换人：第 1、3 步的发送方是 A，第 2 步的发送方是 <strong>B</strong>。所以读表时要盯&quot;这一步是谁在发&quot;，别把 B 的状态变化记到 A 头上。</p></blockquote>',12)),s("figure",a,[(r(),d("svg",g,[...t[0]||(t[0]=[o('<defs><marker id="tcp-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="var(--ink)"></path></marker></defs><rect x="85" y="26" width="130" height="38" rx="8" class="box"></rect><rect x="505" y="26" width="130" height="38" rx="8" class="box"></rect><text x="119" y="50" class="t">客户端 A</text><text x="539" y="50" class="t">服务器 B</text><path d="M150 64V296M570 64V296" class="life"></path><text x="89" y="91" class="s">CLOSED</text><text x="513" y="91" class="s">LISTEN</text><path d="M150 106H570" class="e" marker-end="url(#tcp-arrow)"></path><text x="294" y="96" class="t">① SYN=1，seq=x</text><text x="88" y="125" class="ok">A：SYN-SENT</text><path d="M570 166H150" class="e" marker-end="url(#tcp-arrow)"></path><text x="260" y="156" class="t">② SYN=1，ACK=1，seq=y，ack=x+1</text><text x="493" y="185" class="ok">B：SYN-RCVD</text><path d="M150 226H570" class="e" marker-end="url(#tcp-arrow)"></path><text x="273" y="216" class="t">③ ACK=1，seq=x+1，ack=y+1</text><text x="82" y="247" class="ok">A：ESTABLISHED</text><text x="493" y="270" class="ok">B 收到后：ESTABLISHED</text><text x="165" y="315" class="s">规律：确认号 ack = 对方 SYN 的 seq + 1；第一次只 SYN，第二次 SYN+ACK，第三次只 ACK。</text>',19)])])),t[1]||(t[1]=s("figcaption",null,"纵向虚线表示两端各自的时间推进；读每条消息时先认发送者，再看它令哪一端状态改变。",-1))]),t[3]||(t[3]=o('<p><strong>把数字代进去，状态就再也不会记乱</strong>（设 A 的初始序号 x=100、B 的 y=200）：</p><table tabindex="0"><thead><tr><th>步骤</th><th>报文</th><th>这一步在说什么</th></tr></thead><tbody><tr><td>1</td><td>A→B：SYN=1，seq=<strong>100</strong></td><td>A 说&quot;我把起始编号定为 100&quot;</td></tr><tr><td>2</td><td>B→A：SYN=1，ACK=1，seq=<strong>200</strong>，ack=<strong>101</strong></td><td>B 确认&quot;100 我收到了，下一个请给我 101&quot;；同时报出自己的起始号 200</td></tr><tr><td>3</td><td>A→B：ACK=1，seq=<strong>101</strong>，ack=<strong>201</strong></td><td>A 确认&quot;200 我收到了，下一个请给我 201&quot;</td></tr></tbody></table><p><strong>数字规律（背这一条就够）</strong>：<strong>ack = 对方的 seq + 1</strong>——因为 SYN（和之后的 FIN）本身要占掉一个序号位，所以要 +1；而自己的 seq 一旦定下就固定不变，之后每传一段数据才按字节数往前推。</p><p>记忆抓手：<strong>&quot;一请、二请二应、三应&quot;</strong>——第一次只带 SYN；第二次 SYN 和 ACK 一起带（SYN+ACK 报文）；第三次只带 ACK。四个关键状态按顺序：<strong>CLOSED / LISTEN → SYN-SENT → SYN-RCVD → ESTABLISHED</strong>。</p><p><strong>断开连接（四次挥手，了解过程即可）</strong>：FIN → ACK → FIN → ACK，双方各发一次、各回一次；主动方最后进入 <strong>TIME-WAIT</strong> 等待一段时间（确保最后的 ACK 送达、旧报文消亡）再 CLOSED。考点级别低于握手，记住&quot;挥手四次、比握手多一次&quot;即可。</p><h3 id="滑动窗口-流量控制" tabindex="-1">滑动窗口（流量控制） <a class="header-anchor" href="#滑动窗口-流量控制" aria-label="Permalink to &quot;滑动窗口（流量控制）&quot;">​</a></h3><p><strong>动机</strong>：逐段“发一段、等一次确认”太慢；一口气无限发送又可能压垮接收方或网络。滑动窗口让发送方在一个许可范围内连续发送，既利用线路，又给速度设上限。</p><p>TCP 同时受两扇“窗口”约束：</p><ul><li><strong>接收窗口 <code>rwnd</code></strong>：接收方通告自己还有多少缓存，防止发送方压垮<strong>接收主机</strong>，属于流量控制。</li><li><strong>拥塞窗口 <code>cwnd</code></strong>：发送方根据丢包、确认等网络反馈估计可发送量，防止压垮<strong>网络路径</strong>，属于拥塞控制。</li></ul><p>因此，发送方实际可用的发送窗口上限是：</p><blockquote><p><strong>发送窗口 = min(<code>rwnd</code>, <code>cwnd</code>)</strong></p></blockquote><p><strong>不跳步算例</strong>：接收方通告 <code>rwnd = 12 KB</code>，发送方当前 <code>cwnd = 8 KB</code>，则发送窗口为 <code>min(12, 8) = 8 KB</code>。即使接收方还有 12 KB 空间，网络当前只允许谨慎发送 8 KB。若下一时刻 <code>rwnd = 4 KB</code>、<code>cwnd = 10 KB</code>，则窗口变为 4 KB，瓶颈改成接收方。</p><h4 id="窗口怎样-滑动" tabindex="-1">窗口怎样“滑动” <a class="header-anchor" href="#窗口怎样-滑动" aria-label="Permalink to &quot;窗口怎样“滑动”&quot;">​</a></h4><p>为便于手算，先把数据想成编号为 1、2、3……的等长小段，窗口大小设为 4：</p><table tabindex="0"><thead><tr><th>时刻</th><th>已确认</th><th>当前允许连续发送</th><th>发生了什么</th></tr></thead><tbody><tr><td>t0</td><td>无</td><td>1、2、3、4</td><td>左边界在 1，可连续发 4 段</td></tr><tr><td>t1</td><td>1、2</td><td>3、4、5、6</td><td>收到累计确认，左边界滑到 3，新放进 5、6</td></tr><tr><td>t2</td><td>1～4</td><td>5、6、7、8</td><td>3、4 也确认，窗口继续右移</td></tr></tbody></table><p>这里“确认到 2”可理解为接收方下一段期望 3；已确认的数据移出窗口，右侧才腾出同样数量的新位置。窗口没有把旧数据整体搬家，只是<strong>可发送编号范围的左右边界改变了</strong>。</p><p><strong>反例演示</strong>：若只收到对第 1、2 段的累计确认，却把窗口从 <code>[1,4]</code> 滑成 <code>[5,8]</code>，就等于错误地假设 3、4 也已确认；正确窗口是 <code>[3,6]</code>。</p><h4 id="慢启动在做什么" tabindex="-1">慢启动在做什么 <a class="header-anchor" href="#慢启动在做什么" aria-label="Permalink to &quot;慢启动在做什么&quot;">​</a></h4><p>新连接不知道网络能承受多大流量，因此拥塞窗口不会一开始就开到最大。<strong>慢启动</strong>让 <code>cwnd</code> 从较小值开始，正常收到确认时在每个往返时间内大致成倍增长；到达慢启动门限后转入拥塞避免，增长趋于线性。发生超时等明显拥塞信号时，会显著减小窗口，再谨慎增大。</p><p>“慢启动”名字里的“慢”指<strong>起点小、先试探</strong>，并不表示增长速度一直慢；它的早期增长反而近似指数型。考试通常只要求识别“由小到大探测网络容量”和“<code>cwnd</code> 管网络拥塞”。</p><p><strong>应试动作</strong>：① TCP/UDP 对比表整表背下，特别是“谁用 TCP、谁用 UDP”的典型应用清单；② 三次握手按 SYN → SYN+ACK → ACK 默写；③ 看到“接收方缓存”选 <code>rwnd</code>/流量控制，看到“网络拥塞”选 <code>cwnd</code>/拥塞控制，计算实际窗口就取二者较小值；④ 窗口移动题只让“已经确认”的编号移出左边界。</p>',21))])}const T=e(n,[["render",c]]);export{u as __pageData,T as default};
